#include <cuda_runtime.h>

// Fused relu + Hardtanh(min=-1, max=1).
// relu(x) = max(x, 0); hardtanh clamps to [-1, 1].
// Since relu output >= 0, the lower clamp -1 is inert; result = min(max(x,0), 1).
template<int BLOCK_SIZE>
__global__ void fused_relu_hardtanh_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    // float2 vectorized grid-stride loop over a fixed grid.
    int64_t tid = (int64_t)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x * 2LL;

    int64_t aligned = size & ~1LL;

    for (int64_t i = tid * 2; i < aligned; i += stride) {
        float2 v = *reinterpret_cast<const float2*>(input + i);
        v.x = fminf(fmaxf(v.x, 0.0f), 1.0f);
        v.y = fminf(fmaxf(v.y, 0.0f), 1.0f);
        *reinterpret_cast<float2*>(output + i) = v;
    }

    // Tail element if size is odd
    if (tid == 0 && (size & 1LL) != 0) {
        float v = input[size - 1];
        output[size - 1] = fminf(fmaxf(v, 0.0f), 1.0f);
    }
}

extern "C" void fused_relu_hardtanh_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;   // 4 warps of 64 threads
    const int GRID = 1024;        // fixed grid: 1024 * 256 * 2 = 512K elems per wave
    int grid = GRID;
    int64_t waves = (size + (int64_t)GRID * BLOCK_SIZE * 2 - 1) / ((int64_t)GRID * BLOCK_SIZE * 2);
    if (waves < 1) waves = 1;
    // Keep the grid fixed so the SMs (104) stay filled; grid-stride handles the rest.
    if ((int64_t)GRID * BLOCK_SIZE * 2 > size) {
        // Small input: never launch more blocks than needed
        int needed = (int)((size + (int64_t)BLOCK_SIZE * 2 - 1) / ((int64_t)BLOCK_SIZE * 2));
        if (needed < 1) needed = 1;
        grid = needed;
    }

    fused_relu_hardtanh_impl<BLOCK_SIZE><<<grid, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

