    const float* input,
    int size,
    int config,
    cudaStream_t stream
);

torch::Tensor fused_gelu_tanh_forward(torch::Tensor input, int config) {
    // Normalize device: run on the input's device if CUDA, else move to cuda.
    if (!input.is_cuda()) {
        input = input.to(torch::kCUDA);
    }

    // Normalize dtype to float32 (kernel is float-only).
    if (input.dtype() != torch::kFloat32) {
        input = input.to(torch::kFloat32);
    }

    // Normalize memory layout: dense contiguous float32 view.
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    auto output = torch::empty_like(input);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_gelu_tanh_launcher(
        output.data_ptr<float>(),
        input.data_ptr<float>(),
        static_cast<int>(input.numel()),
        config,
        stream
    );

