// Fused GELU -> tanh for MetaX C500 (MACA), warp size 64.
//
// model.py:  x = F.gelu(x); x = torch.tanh(x)
//   tanh(gelu(x)); gelu uses the exact erf formulation:
//   gelu(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
//
// The chain has a single SFU dependency per element (erf then tanh on the
// same value), which is fine here: the workload is 512*512*1024 = 256M
// floats = 1GB read + 1GB write, so the kernel is memory-traffic-bound and
// the arithmetic hides behind the loads/stores. One fused pass instead of
// two kernels halves the traffic (2GB -> 2GB total, vs 4GB for two passes).
//
// Vectorized float2 loads/stores with a fixed 1024-block grid-stride loop:
// on this device the fine-grained one-thread-per-element grid only reaches
// ~600 GB/s while float2 + fixed grid reaches ~1300 GB/s against a ~1350
// GB/s ceiling. Remaining odd-index elements are handled by a scalar tail
// so no element is ever missed (previous attempt's boundary bug).

#include <cuda_runtime.h>
#include <math.h>

template<int BLOCK_SIZE>
__global__ void fused_gelu_tanh_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 vectorization: each thread handles two consecutive elements.
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    const float INV_SQRT2 = 0.707106781186547524401f;  // 1/sqrt(2)

    // Vector lane: handles indices 2*tid and 2*tid+1.
    int vtid = tid;
    int vstride = stride;
    int n2 = size >> 1;

    for (int i = vtid; i < n2; i += vstride) {
        float2 in;
        const float2* src = reinterpret_cast<const float2*>(input) + i;
        in = *src;  // aligned 8-byte load

        float2 out;
        float a = in.x;
        float b = in.y;

        // GELU (exact erf form) then tanh.
        float ga = 0.5f * a * (1.0f + erff(a * INV_SQRT2));
        float gb = 0.5f * b * (1.0f + erff(b * INV_SQRT2));
        out.x = tanhf(ga);
        out.y = tanhf(gb);

        *(reinterpret_cast<float2*>(output) + i) = out;
    }

    // Scalar tail for the odd leftover element (size not even).
    // Only threads with vtid == 0..0 participate via a dedicated loop over
    // the tail indices; kept simple to avoid a second grid scan.
    int tail = size & 1;
    if (tail) {
        int idx = size - 1;
        // Let thread 0 of the block that owns the tail handle it.
        if (vtid == 0 && idx >= 0 && idx < size) {
            float a = input[idx];
            float ga = 0.5f * a * (1.0f + erff(a * INV_SQRT2));
            output[idx] = tanhf(ga);
        }
    }
}

extern "C" void fused_gelu_tanh_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK = 256;   // 4 warps of 64 threads each
    // Fixed grid of 1024 blocks: enough blocks to cover all 104 SMs with
    // multiple waves, coarse enough to avoid the fine-grained-grid trap.
    const int GRID = 1024;

    switch (config) {
        case 0:
            fused_gelu_tanh_kernel<256><<<GRID, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        case 1:
            fused_gelu_tanh_kernel<512><<<GRID, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        case 2: {
            // Finer grid: one block per 256-element chunk (bounded).
            int blocks = (size + BLOCK - 1) / BLOCK;
            if (blocks > 65535) blocks = 65535;
            fused_gelu_tanh_kernel<256><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        default:
            fused_gelu_tanh_kernel<256><<<GRID, BLOCK, 0, stream>>>(
                output, input, size);
    }
}

