#include <cuda_runtime.h>

// Fused Softsign: out = x / (1 + |x|)
//
// Memory-bound elementwise op on 201M float32 (~806 MB read + 806 MB write).
// Key performance choices for MetaX C500 (104 SMs, warp size 64):
//   - float2 vectorized loads/stores (coalesced 8-byte transactions)
//   - FIXED grid of 1024 blocks x 256 threads with grid-stride loop
//     (a one-thread-per-element grid reaches only ~600 GB/s here;
//      this configuration reaches ~1300 GB/s against a ~1350 GB/s ceiling)

template<int BLOCK_SIZE>
__global__ void softsign_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    // Number of full float2 pairs; the scalar tail is handled separately.
    const size_t n_pairs = size >> 1;

    // Thread-linear index over float2 elements.
    size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    const size_t stride = (size_t)BLOCK_SIZE * (size_t)gridDim.x;

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    // Grid-stride loop over pairs
    for (size_t i = tid; i < n_pairs; i += stride) {
        float2 v = in2[i];

        float2 r;
        r.x = v.x / (1.0f + fabsf(v.x));
        r.y = v.y / (1.0f + fabsf(v.y));

        out2[i] = r;
    }

    // Scalar tail for odd element count
    if ((size & 1ULL) != 0ULL) {
        size_t tail = size - 1;
        if (tid < 64) {  // first warp handles the single tail element cheaply
            if (tid == 0) {
                float v = input[tail];
                output[tail] = v / (1.0f + fabsf(v));
            }
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void softsign_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    // Fixed grid: 1024 blocks x 256 threads = 262144 threads.
    // Ample work per thread for the 201M-element workload, and the grid is
    // exactly sized to keep all 104 SMs fed without over-subscription.
    const int GRID = 1024;

    softsign_kernel_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

