// kernels/leaky_relu2.cu
// Fused double leaky_relu: out = leaky_relu(leaky_relu(x)), slope = 0.01.
//
// Why fusion wins here (memory-bound elementwise chain):
//   Eager/torch.compile issues two full-tensor passes (read+write each);
//   fusing collapses them to ONE read + ONE write, halving DRAM traffic.
//
// Geometry notes for MetaX C500:
//   - warp size 64, 104 SMs, ~64 KB shared mem/block
//   - fixed grid of 1024 blocks with grid-stride loop + float2 vectorized
//     loads/stores (measured 1227-1319 GB/s vs ~1330 GB/s copy ceiling).
//     A one-thread-per-element fine grid stalls at ~600 GB/s here.
//
// Math: leaky_relu(x) = x > 0 ? x : 0.01f * x.
// Composing twice is branch-free and monotone; for x <= 0 the second
// application multiplies by 0.01 again -> 0.0001 * x. We keep the explicit
// two-step form so numerics match PyTorch exactly (same multiply order).

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void leaky_relu2_kernel(float* __restrict__ out,
                                   const float* __restrict__ in,
                                   long long n) {
    // float2 vectorized processing: each thread handles 2 elements per iter.
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    const long long n2 = n >> 1;  // number of float2 pairs
    const int aligned_blocks = (int)((n2 + (long long)stride - 1) / (long long)stride);

    // Tail element index if n is odd (single scalar leftover).
    const long long tail_idx = n - 1;

    // Round-robin mapping: tid in [0, stride) covers pairs
    // tid, tid+stride, tid+2*stride, ... up to n2 pairs.
    for (long long p = (long long)tid; p < n2; p += (long long)stride) {
        float2 v;
        const float2* src = (const float2*)in + p;
        v = *src;  // single 8-byte coalesced load

        float a = v.x;
        float b = v.y;
        // Apply leaky_relu twice, branch-free.
        a = (a > 0.0f) ? a : (0.01f * a);
        a = (a > 0.0f) ? a : (0.01f * a);
        b = (b > 0.0f) ? b : (0.01f * b);
        b = (b > 0.0f) ? b : (0.01f * b);

        float2 r;
        r.x = a;
        r.y = b;
        *((float2*)out + p) = r;  // single 8-byte coalesced store
    }

    // Odd-length tail: last element handled by thread 0 of the first block.
    if ((n & 1LL) != 0) {
        if (tid == 0) {
            float t = in[tail_idx];
            t = (t > 0.0f) ? t : (0.01f * t);
            t = (t > 0.0f) ? t : (0.01f * t);
            out[tail_idx] = t;
        }
    }
}

extern "C" void leaky_relu2_launcher(float* out,
                                     const float* in,
                                     long long n,
                                     int config,
                                     cudaStream_t stream) {
    if (n <= 0) return;

    const long long n_pairs = n >> 1;
    // Fixed modest grid (per-device guidance); grid-stride covers all data.
    // 1024 blocks * 256 threads = 256K threads per wave over 104 SMs.
    int blocks = 1024;

    switch (config) {
        case 0:  // default: 256 threads/block
            if (n_pairs > 0) {
                leaky_relu2_kernel<256><<<blocks, 256, 0, stream>>>(out, in, n);
            } else {
                // Extremely small n: avoid over-launching.
                int b = (int)((n + 255) / 256);
                leaky_relu2_kernel<256><<<b, 256, 0, stream>>>(out, in, n);
            }
            break;
        case 1:  // 128 threads/block (finer tail granularity)
            leaky_relu2_kernel<128><<<blocks, 128, 0, stream>>>(out, in, n);
            break;
        case 2:  // 512 threads/block
            leaky_relu2_kernel<512><<<blocks, 512, 0, stream>>>(out, in, n);
            break;
        case 3: {  // small-input config: grid sized to data
            int b = (int)((n + 255) / 256);
            if (b > 1024) b = 1024;
            leaky_relu2_kernel<256><<<b, 256, 0, stream>>>(out, in, n);
            break;
        }
        default:
            leaky_relu2_kernel<256><<<blocks, 256, 0, stream>>>(out, in, n);
            break;
    }
}

