#include <cuda_runtime.h>
#include <math.h>

// Fused softplus + ReLU.
//
// Key observations:
//  1. ReLU(softplus(x)) == softplus(x) for all x, because softplus(x) > 0.
//     So the ReLU pass is analytically a no-op and needs no extra memory pass.
//  2. The naive softplus(x) = log1p(exp(x)) has a chained SFU dependency
//     (expf result fed straight into log1pf) which starves the scheduler on
//     this device. Instead use the stable form:
//         softplus(x) = max(x, 0) + log1p(exp(-|x|))
//     exp(-|x|) is bounded in (0, 1], so log1pf is always accurate, and the
//     max(x,0) term gives the scheduler independent integer/max work while
//     the SFU chain is in flight.
//
// Memory pattern: float2 (2-wide) vectorized loads/stores with a fixed
// 1024-block grid-stride loop. On this device the scalar one-thread-per-element
// grid only reaches ~600 GB/s while float2 + fixed grid reaches ~1300 GB/s.

template<int BLOCK_SIZE>
__global__ void fused_softplus_relu_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized element index pairs: thread t handles elements (2t, 2t+1).
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int vstride = 2 * stride;
    int vtid = 2 * tid;

    // Fast path: whole float2 pairs in bounds.
    int vsize = size & ~1;
    for (int i = vtid; i < vsize; i += vstride) {
        float2 in = *reinterpret_cast<const float2*>(input + i);
        float2 out;
        float a = in.x;
        float b = in.y;
        float ma = fmaxf(a, 0.0f);
        float mb = fmaxf(b, 0.0f);
        out.x = ma + log1pf(expf(-fmaxf(a, -a)));
        out.y = mb + log1pf(expf(-fmaxf(b, -b)));
        *reinterpret_cast<float2*>(output + i) = out;
    }

    // Tail: odd-sized remainder.
    if (vsize < size) {
        int rem = size - vsize;  // always 1 when size is odd
