// Fused abs + ReLU6 (min(max(|x|, 0), 6)).
//
// Memory-bound elementwise pair on MetaX C500: the arithmetic is free, the
// cost is moving 2*N*4 bytes. Strategy per the device profile:
//   - float2 vectorized loads/stores (coalesced 8-byte transactions)
//   - fixed grid of 1024 blocks, grid-stride loop (no tiny per-element grid)
//   - branch-free body: fabsf then clamped value chosen without divergence
//
// 256 * 1024 = 262144 threads per wave on 104 SMs; each thread walks an
// aligned (2-element) strided range.

__device__ __forceinline__ float relu6_abs(float v) {
    float a = fabsf(v);
    // branch-free min(max(a,0.f),6.f)
    float b = fmaxf(a, 0.0f);
    return fminf(b, 6.0f);
}

template<int BLOCK_SIZE>
__global__ void fused_abs_relu6_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized view: process pairs.
    const int vec_size = size >> 1;          // number of float2 elements
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    // Grid-stride loop over aligned float2 elements.
    for (int i = tid; i < vec_size; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = relu6_abs(v.x);
        r.y = relu6_abs(v.y);
        out2[i] = r;
