// Fused ReLU + Abs.
// relu(x) = max(x, 0); abs(relu(x)) = max(x, 0) since relu(x) >= 0.
// So the whole chain collapses to a single max(x, 0) pass.
//
// Performance strategy for MetaX C500 (warp size 64, 104 SMs):
//  - float4 (128-bit) vectorized loads/stores to maximize memory throughput
//  - fixed grid of 1024 blocks x 256 threads, grid-stride loop
//    (avoids the one-thread-per-element trap that tops out at ~600 GB/s)
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_relu_abs_impl(float* __restrict__ output,
                                    const float* __restrict__ input,
                                    int64_t size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;

    const int64_t aligned = (size / 4) * 4;

    // Vectorized body: 4 floats per iteration.
    for (int64_t i = (int64_t)tid * 4; i < aligned; i += stride * 4) {
        float4 in = *reinterpret_cast<const float4*>(input + i);
        float4 out;
        out.x = fmaxf(in.x, 0.0f);
        out.y = fmaxf(in.y, 0.0f);
        out.z = fmaxf(in.z, 0.0f);
        out.w = fmaxf(in.w, 0.0f);
        *reinterpret_cast<float4*>(output + i) = out;
    }

    // Scalar tail for the remaining elements.
    int64_t tail = (int64_t)tid + aligned;
    if (tail < size) {
        output[tail] = fmaxf(input[tail], 0.0f);
    }
}

