    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;
    fused_relu_abs_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
