// kernels/log_tanh.cu
// Fused: x -> log(x) -> tanh(log(x)) for positive x.
// Performance-oriented variant:
//   * float4 vectorized loads/stores (coalesced 16-byte accesses)
//   * fixed grid of 104*8 blocks (fills all 104 SMs with 8 waves each),
//     grid-stride loop so it works for any size
//   * 256 threads per block = 4 warps of 64 lanes (C500 warp size is 64)
// Math is unchanged from the previous (correct) scalar version:
//   v = logf(v); v = tanhf(v);
#include <cuda_runtime.h>

// Vectorized body: 4 independent elements per thread -> ILP hides SFU latency.
__device__ __forceinline__ float4 log_tanh4(float4 v) {
    float4 r;
    r.x = tanhf(logf(v.x));
    r.y = tanhf(logf(v.y));
    r.z = tanhf(logf(v.z));
    r.w = tanhf(logf(v.w));
    return r;
}

template<int BLOCK_SIZE>
__global__ void log_tanh_vec_kernel(float* __restrict__ output,
                                    const float* __restrict__ input,
                                    unsigned long long size) {
    // float4 view of the bulk
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    const float4* in4 = reinterpret_cast<const float4*>(input);
    float4* out4 = reinterpret_cast<float4*>(output);

    const unsigned long long n4 = size >> 2;  // number of complete float4s

    // Grid-stride over float4 elements: 4 floats processed per iteration.
    for (unsigned long long i = tid; i < n4; i += stride) {
        out4[i] = log_tanh4(in4[i]);
    }

    // Scalar tail for the remaining 0..3 elements
    const unsigned long long tail_base = n4 << 2;
    const int lanes = BLOCK_SIZE;
    for (unsigned long long j = tail_base + (unsigned long long)tid;
         j < size;
         j += (unsigned long long)lanes) {
        output[j] = tanhf(logf(input[j]));
    }
}

extern "C" void log_tanh_launcher(float* output,
                                  const float* input,
                                  unsigned long long size,
                                  cudaStream_t stream) {
    if (size == 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed grid: 104 SMs * 8 blocks/SM = 832 blocks.
    // At 256 threads and modest register pressure this keeps every SM busy
    // while each block loops over many chunks (grid-stride), avoiding the
    // one-thread-per-element trap that only reached ~600 GB/s here.
    const int GRID = 832;

    // n4 == 0 is fine: the vector loop is skipped and the tail handles all.
    log_tanh_vec_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(output, input, size);
