// kernels/fused_selu_trunc.cu
// Fused selu(x) -> trunc(x) single-pass kernel.
//
// Memory-bound elementwise chain (each op touches the full tensor), so the win
// comes from removing one full memory round-trip, not from faster arithmetic.
// Vectorized with float2 loads and a grid-stride loop over a fixed 1024-block
// grid: measured sweet spot for this device is ~1024 blocks, and scalar
// one-thread-per-element grids stall at far lower bandwidth here.
#include <cuda_runtime.h>

// selu(x) = scale * (max(0,x) + min(0, alpha * (exp(x) - 1)))
// with the standard torch defaults alpha=1.6732632423543772,
// scale=1.0507009873554805.
__device__ __forceinline__ float selu_f32(float x) {
    const float alpha = 1.6732632423543772f;
    const float scale = 1.0507009873554805f;
    float out;
    if (x > 0.0f) {
        out = scale * x;
    } else {
        float e = expf(x);
        out = scale * (alpha * (e - 1.0f));
    }
    return out;
}

template<int BLOCK_SIZE>
__global__ void fused_selu_trunc_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    // Grid-stride in units of float2 pairs.
    const int64_t total_pairs = size / 2;
    const int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x;

    int64_t idx = (int64_t)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    for (; idx < total_pairs; idx += stride) {
        int64_t b = idx * 2;
        float2 in = *reinterpret_cast<const float2*>(input + b);
        float2 r;
        r.x = truncf(selu_f32(in.x));
        r.y = truncf(selu_f32(in.y));
        *reinterpret_cast<float2*>(output + b) = r;
    }

    // Tail element for odd sizes.
    if (threadIdx.x == 0 && blockDim.x * gridDim.x > 0) {
        if (size & 1) {
            int64_t t = size - 1;
            float v = input[t];
            output[t] = truncf(selu_f32(v));
        }
    }
}

extern "C" void fused_selu_trunc_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;      // 4 warps of 64 threads
    const int GRID = 1024;           // fixed grid: measured sweet spot here

