#include <cuda_runtime.h>
#include <math.h>

// Fused: out = Mish(tanh(x)), where Mish(z) = z * tanh(softplus(z))
//   softplus(z) = log(1 + exp(z)) computed in a numerically safe way:
//   for z >= 0:  z + log1p(exp(-z))   (argument of exp is <= 0, no overflow)
//   for z <  0:  log1p(exp(z))        (exp(z) <= 1, no overflow)
//
// This is a memory-bound elementwise chain; the entire op chain reads the
// input once and writes the output once, versus 5 reads / 4 writes when
// launched as separate kernels (tanh, softplus, tanh, mul).
//
// Layout: consecutive threads handle consecutive float2 pairs -> fully
// coalesced 8-byte loads/stores. Fixed 1024-block grid-stride loop keeps the
// grid coarse (warp size is 64 on this device; a one-thread-per-element grid
// is a documented performance trap here).

__device__ __forceinline__ float safe_softplus(float z) {
    // Branch-free-safe: exp argument is always <= 0.
    float a = fabsf(z);
    // exp(-a) in (0, 1]; for large a this underflows to 0 -> log1p(0) = 0.
    float p = expf(-a);
    float sp = log1pf(p);
    // Add z when positive: max(z, 0) == (z + a) * 0.5f
    return sp + fmaf(z + a, 0.5f, 0.0f);
}

__device__ __forceinline__ float fast_tanh(float x) {
    // tanhf is a single SFU-class op on this device; keep it (Mish's inner
    // tanh is a true chained-SFU dependency, unavoidable).
    return tanhf(x);
}

template<int BLOCK_SIZE>
__global__ void fused_tanh_mish_impl(float* __restrict__ output,
                                     const float* __restrict__ input,
                                     int size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // Total float elements; pairs consumed from tid*2 onward via stride*2.
    const int pairs = size >> 1;

    // --- Vectorized float2 section: handles all complete pairs ---
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    for (int i = tid; i < pairs; i += stride) {
        float2 v = in2[i];

        float t0 = fast_tanh(v.x);
        float t1 = fast_tanh(v.y);

        float s0 = safe_softplus(t0);
        float s1 = safe_softplus(t1);

        float h0 = fast_tanh(s0);
        float h1 = fast_tanh(s1);

        float2 r;
        r.x = t0 * h0;
        r.y = t1 * h1;
        out2[i] = r;
    }

    // --- Tail: odd element when size is not even ---
    // Only one thread per block (thread 0 of some block) handles it; guard
    // with a simple stride walk over the single remaining index.
    const int tail_start = pairs * 2;
    if (size - tail_start == 1) {
        const int tail_id = blockIdx.x;  // spread across blocks
        if (tail_id < 1) {               // exactly one element to write
            float v = input[tail_start];
            float t = fast_tanh(v);
            float s = safe_softplus(t);
            output[tail_start] = t * fast_tanh(s);
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_tanh_mish_launcher(
    float* output,
    const float* input,
