// kernels/fused_relu_log1p.cu
// Fused y = log1p(relu(x)) for float32 tensors.
//
// Memory-bound elementwise chain on MetaX C500 (warp size 64, 104 SMs).
// One pass over the input instead of two, using float2 vectorized loads and
// a fixed grid-stride loop so the grid stays coarse (a one-thread-per-element
// grid is a documented performance trap on this device).

#include <cuda_runtime.h>

// log1p(x) computed as a single SFU chain on the clamped value.
// After relu, x >= 0, so 1.0f + x >= 1.0f and the sum cannot lose precision
// through catastrophic cancellation; the direct form is both safe and cheap.
__device__ __forceinline__ float relu_log1p(float v) {
    float a = v < 0.0f ? 0.0f : v;
    return log1pf(a);
}

template<int BLOCK_SIZE>
__global__ void fused_relu_log1p_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    // Vectorized body: each thread handles 2 floats per iteration.
    const unsigned long long tid = static_cast<unsigned long long>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride = static_cast<unsigned long long>(BLOCK_SIZE) * gridDim.x;

    const unsigned long long size2 = size >> 1;
    const unsigned long long base2 = tid;

    // Main vectorized loop over float2 pairs
    for (unsigned long long i = base2; i < size2; i += stride) {
        float2 in = reinterpret_cast<const float2*>(input)[i];
        float2 out;
        out.x = relu_log1p(in.x);
        out.y = relu_log1p(in.y);
        reinterpret_cast<float2*>(output)[i] = out;
    }

    // Tail element (odd element count)
    const unsigned long long tail = size2 + tid;
    if (tail < size) {
        output[tail] = relu_log1p(input[tail]);
    }
}

extern "C" void fused_relu_log1p_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    if (size == 0) {
        return;
    }

    const int BLOCK_SIZE = 256;  // 4 warps of 64 threads
    // Fixed, coarse grid: 1024 blocks covers 104 SMs several times over and
    // lets each block walk the array with a grid-stride loop.
    const int GRID = 1024;

    fused_relu_log1p_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

